// Signs the release build with the keystore named in the environment (ADR-0012).
//
// android/ is generated by `expo prebuild` and not committed, so the signing config is added
// here. Gradle reads the path and passwords from the environment at build time, so nothing
// secret is written into the generated project. With no signing variables set, the build keeps
// Expo's debug signing, which is what PR CI uses.
const { withAppBuildGradle } = require("@expo/config-plugins");

const SIGNING_ENV = [
  "ANDROID_KEYSTORE_PATH",
  "ANDROID_KEYSTORE_PASSWORD",
  "ANDROID_KEY_ALIAS",
  "ANDROID_KEY_PASSWORD",
];

const RELEASE_SIGNING_CONFIG = `        release {
            storeFile file(System.getenv("ANDROID_KEYSTORE_PATH"))
            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias System.getenv("ANDROID_KEY_ALIAS")
            keyPassword System.getenv("ANDROID_KEY_PASSWORD")
        }
`;

function applyReleaseSigning(gradle, env = process.env) {
  const present = SIGNING_ENV.filter((name) => env[name]);
  if (present.length === 0) return gradle;

  const missing = SIGNING_ENV.filter((name) => !env[name]);
  if (missing.length > 0) {
    throw new Error(`Release signing needs all of ${SIGNING_ENV.join(", ")}; missing: ${missing.join(", ")}`);
  }

  const signingConfigsOpen = /signingConfigs\s*\{\r?\n/;
  if (!signingConfigsOpen.test(gradle)) {
    throw new Error("Release signing: no signingConfigs block in app/build.gradle");
  }
  let out = gradle.replace(signingConfigsOpen, (open) => open + RELEASE_SIGNING_CONFIG);

  // Only the release build type switches to the release key; the debug build type keeps the debug key.
  const releaseDebugKey = /(release\s*\{[^}]*?)signingConfig\s+signingConfigs\.debug/;
  if (!releaseDebugKey.test(out)) {
    throw new Error("Release signing: no release buildType signed with signingConfigs.debug to replace");
  }
  out = out.replace(releaseDebugKey, "$1signingConfig signingConfigs.release");
  return out;
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });

module.exports = withReleaseSigning;
module.exports.applyReleaseSigning = applyReleaseSigning;
